using Microsoft.AspNetCore.Mvc;
using System.Text;

public class ReportController : Controller
{
    // ── Pattern: ASP.NET request termination ──
    // Response.End() + Response.Write() → return a FileContentResult.
    // No ThreadAbortException exists in .NET 8; Response.End() would throw
    // PlatformNotSupportedException.
    [HttpPost]
    public IActionResult Export()
    {
        var data = GenerateReport();

        // Return the file directly — the framework handles headers and
        // flushing the response. No Response.Clear/Write/End needed.
        return File(
            Encoding.UTF8.GetBytes(data),
            "text/csv",
            "report.csv");
    }

    // ── Pattern: Response.Redirect(url, true) + ThreadAbortException catch ──
    // Every redirect becomes a RedirectResult returned from the action.
    // The catch (ThreadAbortException) block is deleted entirely — it was
    // only needed because Response.Redirect(url, true) called Thread.Abort
    // internally, which no longer exists.
    [HttpPost]
    public IActionResult ProcessReport()
    {
        if (!User.Identity?.IsAuthenticated ?? true)
        {
            return Redirect("/login");
        }

        try
        {
            ProcessRequest();
            return Redirect("/success");
        }
        catch (Exception ex)
        {
            LogError(ex);
            return Redirect("/error");
        }
    }

    // Stubs — replace with your real implementations
    private string GenerateReport() => "col1,col2\nval1,val2";
    private void ProcessRequest() { }
    private void LogError(Exception ex) { }
}

